  "7422baf70605": {
    "pt-BR": "). O texto ficou selecionado: toque e segure para copiar.",
    "en": "). The text is selected: press and hold to copy."
  },
  "74288f0d1b67": {
    "pt-BR": "Pode ser que o endereço que você está usando não deixe passar a conexão contínua que a tela precisa,\n        que a sua sessão no painel tenha vencido (recarregue a página e entre de novo), ou que o serviço da tela\n        tenha caído. Este painel não tem um endereço alternativo configurado: peça a quem instalou para configurar\n        um, ou para conferir o serviço da tela.",
    "en": "Your access address may block the continuous connection the screen needs, your dashboard session may have expired (reload and sign in again), or the screen service may be down. No alternative address is configured: ask the installer to configure one or check the screen service."
  },
  "74301c182360": {
    "pt-BR": "Não consegui marcar a conversa como não lida: ",
    "en": "Could not mark the chat as unread: "
  },
  "74386f51922d": {
    "pt-BR": "Antes desta tela, dar uma chave ao agente exigia alguém com acesso à máquina editando arquivo à mão. Agora é um campo, e a chave fica guardada cifrada em vez de escrita em texto puro num arquivo de configuração.",
    "en": "Previously, giving an agent a key required machine access and manual file editing. Now you enter it in a field, and it is stored encrypted instead of as plaintext in a configuration file."
  },
  "7441c87e411e": {
    "pt-BR": "Não deu para confirmar de onde veio o pedido. Recarregue a página e tente de novo.",
    "en": "Could not verify the request origin. Reload the page and try again."
  },
  "7444e37ea660": {
    "pt-BR": "Conectado",
    "en": "Connected"
  },
