  "9e4340088017": {
    "pt-BR": "chegou para ",
    "en": "delivered to "
  },
  "9e44d5bfbb75": {
    "pt-BR": "O nome, o papel e o que ele faz para você.",
    "en": "Its name, role and what it does for you."
  },
  "9e5086a8c80f": {
    "pt-BR": " não roda por aqui: ",
    "en": " cannot run here: "
  },
