  "ad88664b484e": {
    "pt-BR": " como aplicativo na tela inicial do aparelho.",
    "en": " as an app on your device's home screen."
  },
  "ad981c718c27": {
    "pt-BR": "Com vários agentes trabalhando, você vê de relance quem espera por você e deixa para depois uma resposta que não quer ler agora, sem perder o fio.",
    "en": "With multiple agents working, see at a glance who is waiting for you and leave a reply for later without losing track."
  },
  "adb85d845d4f": {
    "pt-BR": "a rede caiu antes da resposta (",
    "en": "the network disconnected before the reply ("
  },
