  "ffcb68e8dda8": {
    "pt-BR": "Os números de verdade deste agente, lidos agora: o tamanho de cada camada da memória, as operações do sistema, as suas rotinas e a sessão.",
    "en": "This agent's actual numbers, read now: size of each memory layer, system operations, your routines and the session."
  },
  "ffdab0870939": {
    "pt-BR": "Verde rodou e deu certo. Vermelho falhou: o programa terminou com erro, ou o registro da própria rotina disse que falhou. Amarelo pede atenção: não rodou quando devia (listrado), foi cancelada, rodou com aviso, ou reiniciou. Cinza é sem dado.",
    "en": "Green means success. Red means a program error or a failure recorded by the routine itself. Yellow needs attention: missed scheduled run (striped), cancellation, warning or restart. Gray means no data."
  },
